window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b7cbbecde18e5583"]={"versions": [{"id": "FIG-b7cbbecde18e5583", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses der Funktion <code>E2E_P05Forward()</code> im AUTOSAR E2E-Protokoll (Profil 5). Das Diagramm visualisiert den Teilschritt „Write Counter“ für die Weiterleitung (Forwarding) von E2E-geschützten Datenpaketen innerhalb der AUTOSAR-Basissoftware bzw. des E2E-Bibliotheksmoduls.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivität / Kontext</strong>: <code>E2E_P05Forward()</code></li>\n<li><strong>Zustandsstruktur / Variablen</strong>:</li>\n<li><code>State-&gt;Counter</code>: 1-Byte-Zähler (<code>uint8</code>) zur Erkennung von Paketfolgen und Wiederholungen.</li>\n<li><code>ForwardStatus</code>: Status-Rückgabewert der vorhergehenden Auswertung bzw. Prüfung (Prüfwerte: <code>E2E_P_REPEATED</code>, <code>E2E_P_WRONGSEQUENCE</code>).</li>\n<li><code>Config-&gt;MaxDeltaCounter</code>: Konfigurationsparameter für die maximal zulässige Zählerdifferenz.</li>\n<li><code>Data</code>: Byte-Array des zu übertragenden Datenpakets.</li>\n<li><code>Offset</code>: Konfigurierter Byte-Offset innerhalb des Datenpuffers.</li>\n<li><strong>Knoten / Aktionen</strong>:</li>\n<li>Startknoten (Initial Node) und Endknoten (Activity Final Node).</li>\n<li>Verzweigungs- und Zusammenführungsknoten (Decision & Merge Nodes).</li>\n<li>Aktionsknoten: <code>State-&gt;Counter --</code></li>\n<li>Aktionsknoten: <code>State-&gt;Counter = State-&gt;Counter + Config-&gt;MaxDeltaCounter</code></li>\n<li>Aktionsknoten: <code>Copy 1-byte State-&gt;Counter on byte Data[Offset+2] in Little Endian order</code></li>\n<li>Notizsymbol (Note): Spezifikation des Datentyps <code>uint8</code> und Überlaufverhaltens (nach <code>0xFF</code> folgt <code>0</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Beginn am Startknoten der Funktion <code>E2E_P05Forward()</code>.</li>\n<li>Erste Verzweigung prüft Bedingung <code>if ForwardStatus == E2E_P_REPEATED</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[TRUE]</code>: Dekrementierung des Zählers (<code>State-&gt;Counter --</code>), anschließend Übergang zur Zusammenführung vor dem Schreibschritt.</li>\n<li><code>[FALSE]</code>: Weiterleitung zur zweiten Verzweigung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Zweite Verzweigung prüft Bedingung <code>if ForwardStatus == E2E_P_WRONGSEQUENCE</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[TRUE]</code>: Anpassung des Zählers über <code>State-&gt;Counter = State-&gt;Counter + Config-&gt;MaxDeltaCounter</code>, danach Übergang zur Zusammenführung.</li>\n<li><code>[FALSE]</code>: Pfad <code>else</code> ohne Zählermodifikation direkt zur Zusammenführung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Nach dem Merge-Knoten aller drei Pfade: Ausführen der Aktion <code>Copy 1-byte State-&gt;Counter on byte Data[Offset+2] in Little Endian order</code>.</li>\n<li>Erreichen des Endknotens.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm ist normativer Bestandteil der E2E-Profil-5-Spezifikation (referenziert über Anforderung <code>[PRS_E2E_00620]</code>). Implementierungen müssen den Zähler <code>State-&gt;Counter</code> als <code>uint8</code> mit Modulo-256-Arithmetik führen (Überlauf nach <code>0xFF</code> auf <code>0</code>, Unterlauf bei <code>0x00</code> auf <code>0xFF</code>). Bei Wiederholungen (<code>E2E_P_REPEATED</code>) wird der Zähler dekrementiert, um den wiederholten Zustand nachzubilden; bei Sequenzfehlern (<code>E2E_P_WRONGSEQUENCE</code>) wird er um <code>MaxDeltaCounter</code> erhöht, um den Folgefehler abzubilden. Die Ablage im Datenpuffer erfolgt zwingend an Byte-Position <code>Data[Offset + 2]</code> in Little-Endian-Formatierung.</p>"}, {"id": "FIG-783ac8f557d8e560", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses der Funktion <code>E2E_P05Forward()</code> im AUTOSAR E2E-Protokoll (Profil 5). Das Diagramm visualisiert den Teilschritt „Write Counter“ für die Weiterleitung (Forwarding) von E2E-geschützten Datenpaketen innerhalb der AUTOSAR-Basissoftware bzw. des E2E-Bibliotheksmoduls.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivität / Kontext</strong>: <code>E2E_P05Forward()</code></li>\n<li><strong>Zustandsstruktur / Variablen</strong>:</li>\n<li><code>State-&gt;Counter</code>: 1-Byte-Zähler (<code>uint8</code>) zur Erkennung von Paketfolgen und Wiederholungen.</li>\n<li><code>ForwardStatus</code>: Status-Rückgabewert der vorhergehenden Auswertung bzw. Prüfung (Prüfwerte: <code>E2E_P_REPEATED</code>, <code>E2E_P_WRONGSEQUENCE</code>).</li>\n<li><code>Config-&gt;MaxDeltaCounter</code>: Konfigurationsparameter für die maximal zulässige Zählerdifferenz.</li>\n<li><code>Data</code>: Byte-Array des zu übertragenden Datenpakets.</li>\n<li><code>Offset</code>: Konfigurierter Byte-Offset innerhalb des Datenpuffers.</li>\n<li><strong>Knoten / Aktionen</strong>:</li>\n<li>Startknoten (Initial Node) und Endknoten (Activity Final Node).</li>\n<li>Verzweigungs- und Zusammenführungsknoten (Decision & Merge Nodes).</li>\n<li>Aktionsknoten: <code>State-&gt;Counter --</code></li>\n<li>Aktionsknoten: <code>State-&gt;Counter = State-&gt;Counter + Config-&gt;MaxDeltaCounter</code></li>\n<li>Aktionsknoten: <code>Copy 1-byte State-&gt;Counter on byte Data[Offset+2] in Little Endian order</code></li>\n<li>Notizsymbol (Note): Spezifikation des Datentyps <code>uint8</code> und Überlaufverhaltens (nach <code>0xFF</code> folgt <code>0</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Beginn am Startknoten der Funktion <code>E2E_P05Forward()</code>.</li>\n<li>Erste Verzweigung prüft Bedingung <code>if ForwardStatus == E2E_P_REPEATED</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[TRUE]</code>: Dekrementierung des Zählers (<code>State-&gt;Counter --</code>), anschließend Übergang zur Zusammenführung vor dem Schreibschritt.</li>\n<li><code>[FALSE]</code>: Weiterleitung zur zweiten Verzweigung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Zweite Verzweigung prüft Bedingung <code>if ForwardStatus == E2E_P_WRONGSEQUENCE</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[TRUE]</code>: Anpassung des Zählers über <code>State-&gt;Counter = State-&gt;Counter + Config-&gt;MaxDeltaCounter</code>, danach Übergang zur Zusammenführung.</li>\n<li><code>[FALSE]</code>: Pfad <code>else</code> ohne Zählermodifikation direkt zur Zusammenführung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Nach dem Merge-Knoten aller drei Pfade: Ausführen der Aktion <code>Copy 1-byte State-&gt;Counter on byte Data[Offset+2] in Little Endian order</code>.</li>\n<li>Erreichen des Endknotens.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm ist normativer Bestandteil der E2E-Profil-5-Spezifikation (referenziert über Anforderung <code>[PRS_E2E_00620]</code>). Implementierungen müssen den Zähler <code>State-&gt;Counter</code> als <code>uint8</code> mit Modulo-256-Arithmetik führen (Überlauf nach <code>0xFF</code> auf <code>0</code>, Unterlauf bei <code>0x00</code> auf <code>0xFF</code>). Bei Wiederholungen (<code>E2E_P_REPEATED</code>) wird der Zähler dekrementiert, um den wiederholten Zustand nachzubilden; bei Sequenzfehlern (<code>E2E_P_WRONGSEQUENCE</code>) wird er um <code>MaxDeltaCounter</code> erhöht, um den Folgefehler abzubilden. Die Ablage im Datenpuffer erfolgt zwingend an Byte-Position <code>Data[Offset + 2]</code> in Little-Endian-Formatierung.</p>"}], "trans": [{"from": "FIG-b7cbbecde18e5583", "to": "FIG-783ac8f557d8e560", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
